package ai.idraak.stepskyscraper.ads

import ai.idraak.stepskyscraper.BuildConfig
import ai.idraak.stepskyscraper.core.ads.AdsEnvironment
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

/** Per-variant ad facts generated by app/build.gradle.kts (`androidComponents.onVariants`). */
@Module
@InstallIn(SingletonComponent::class)
object AdsEnvironmentModule {
    @Provides
    @Singleton
    fun adsEnvironment(): AdsEnvironment = AdsEnvironment(
        isProdRelease = BuildConfig.ADS_PROD_RELEASE,
        liveAppId = BuildConfig.ADMOB_LIVE_APP_ID,
        liveRewardedUnitId = BuildConfig.ADMOB_LIVE_REWARDED_UNIT_ID,
        testDeviceHashedId = BuildConfig.ADMOB_TEST_DEVICE_ID,
        umpDebugGeographyEea = BuildConfig.ADMOB_UMP_DEBUG_EEA,
    )
}
